import React from "react";
import { Checkbox, Form, Input, Spin } from "antd";

import { MyPay } from "../../types";
import { ConfigHeading } from "../ConfigHeading";
import { getMyPayConfig, saveMyPayConfig } from "../../remote";

export const AppMyPay = () => {
    const [formValues, setFormValues] = React.useState<MyPay>();
    const [formDisabled, setFormDisabled] = React.useState(false);
    const [form] = Form.useForm<MyPay>();

    React.useEffect(() => {
        getMyPayConfig().then((res) => {
            if (res.status === 200) {
                setFormValues(res.data);
                form.setFieldsValue(res.data);
            }
        });

        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const onFinish = async (values: MyPay) => {
        setFormDisabled(true);

        if (formValues) {
            const res = await saveMyPayConfig({
                ...formValues,
                ShowSummary: values.ShowSummary,
            });
            setFormValues(res.data);
        }
        setFormDisabled(false);
    };

    return (
        <Spin
            spinning={formValues === undefined || formDisabled}
            tip={formDisabled ? "Saving configuration" : "Loading My Pay configuration"}>
            <Form
                name="ss-links"
                onFinish={onFinish}
                autoComplete={"off"}
                layout="horizontal"
                form={form}
                disabled={formDisabled}>
                <ConfigHeading title="My Pay Configuration" />
                <div className="ss-app-config-box shadow ss-app-config-dashboard">
                    <Form.Item name={["Id"]} noStyle>
                        <Input type="hidden" />
                    </Form.Item>
                    <Form.Item name={["Name"]} noStyle>
                        <Input type="hidden" />
                    </Form.Item>
                    <Form.Item name={["Enabled"]} noStyle>
                        <Input type="hidden" />
                    </Form.Item>
                    <Form.Item
                        label="Host URL"
                        name="Url_"
                        rules={[
                            {
                                type: "url",
                                message: "Invalid Link address.",
                            },
                        ]}>
                        <Input />
                    </Form.Item>
                    <Form.Item name={["ShowSummary"]} label="Show Summary" valuePropName="checked">
                        <Checkbox />
                    </Form.Item>
                </div>
            </Form>
        </Spin>
    );
};
